// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1", wrapper.GetAPIIndex)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/game/products", wrapper.ListGameProducts)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/library/datasets", wrapper.ListLibraryDatasets)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/game/entity-types", wrapper.ListGameEntityTypes)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/game/entities", wrapper.ListGameEntities)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/game/entity-summaries", wrapper.ListGameEntitySummaries)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/game/sitemap-entries", wrapper.ListGameSitemapEntries)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/game/categories", wrapper.ListGameCategories)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/game/entities/{id}", wrapper.GetGameEntity)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/game/entities/{id}/relationships", wrapper.ListGameEntityRelationships)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/game/entities/{id}/quality", wrapper.GetGameEntityQuality)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/game/entities/{id}/versions", wrapper.ListGameEntityVersions)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/game/entities/{id}/comparison", wrapper.GetGameEntityComparison)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/game/coverage", wrapper.ListGameCoverage)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/game/source-policies", wrapper.ListGameSourcePolicies)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/game/relation-types", wrapper.ListGameRelationTypes)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/livez", wrapper.GetLiveness)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/readyz", wrapper.GetReadiness)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/analytics/overview", wrapper.GetAnalyticsOverview)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/analytics/events", wrapper.IngestAnalyticsEvents)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/v1/indexnow", wrapper.SubmitIndexNow)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/media/{id}", wrapper.GetCatalogMedia)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/graphql", wrapper.ExecuteGraphQL)

	return m
}

